pub(crate) fn it_put(mut c: &mut crate::port::Cells, b: &[u8]) -> i32 {
    // The ASCII text of b as code points appended to c; answers where they start.
    let start: i32 = crate::port::blob_len(b);
    let mut i: i32 = 0;
    while i < start {
        crate::port::cells_push(c, crate::port::blob_u8(b, i));
        i += 1;
    }
    return 0;
}
