#[test]
fn test_a_locale_tag_names_a_language() {
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("")[..]), 0, "no tag");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("e")[..]), 0, "one letter is no tag");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("en")[..]), 1, "en");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("EN-us")[..]), 1, "case does not matter, a region follows");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("en_GB")[..]), 1, "an underscore too");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("de-CH")[..]), 2, "de");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("fr")[..]), 3, "fr");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("es-419")[..]), 4, "es");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("pt-BR")[..]), 5, "pt");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("it")[..]), 6, "it");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("nl-BE")[..]), 7, "nl");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("zh-Hans")[..]), 99, "a language without a table");
    crate::testport::assert_eq(it_lang(&crate::testport::text_blob("english")[..]), 99, "a word is not a tag");
}
#[test]
fn test_the_join_without_a_locale() {
    let none: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::testport::assert_eq(it_join(none, 65, &crate::testport::text_blob("long")[..]), 1, "`A` + `long`: joined, flagged (the union of the tables has `A`)");
    crate::testport::assert_eq(it_join(none, 73, &crate::testport::text_blob("t")[..]), 1, "`I` + `t`: flagged too");
    crate::testport::assert_eq(it_join(none, 69, &crate::testport::text_blob("verything")[..]), 1, "`E` is a word in Spanish, Italian, Portuguese");
    crate::testport::assert_eq(it_join(none, 84, &crate::testport::text_blob("he")[..]), 0, "`T` + `he`: no language has a word `T`");
    crate::testport::assert_eq(it_join(none, 81, &crate::testport::text_blob("uiet")[..]), 0, "`Q` + `uiet`");
    crate::testport::assert_eq(it_join(none, 65, &crate::testport::text_blob("")[..]), 1, "no word after it: still flagged");
}
#[test]
fn test_the_join_with_a_locale() {
    let en: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let de: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let zh: &mut crate::port::Cells = &mut crate::port::Cells::new();
    it_put(en, &crate::testport::text_blob("en-US")[..]);
    it_put(de, &crate::testport::text_blob("de")[..]);
    it_put(fr, &crate::testport::text_blob("fr")[..]);
    it_put(zh, &crate::testport::text_blob("zh")[..]);
    // English lists: the words a one-letter word is followed by, and the rest of a word the letter begins.
    crate::testport::assert_eq(it_join(en, 65, &crate::testport::text_blob("long")[..]), 2, "`A` + `long`: a space, the letter is a word");
    crate::testport::assert_eq(it_join(en, 73, &crate::testport::text_blob("was")[..]), 2, "`I` + `was`");
    crate::testport::assert_eq(it_join(en, 73, &crate::testport::text_blob("t")[..]), 0, "`I` + `t`: `It`, sure");
    crate::testport::assert_eq(it_join(en, 65, &crate::testport::text_blob("t")[..]), 0, "`A` + `t`: `At`");
    crate::testport::assert_eq(it_join(en, 79, &crate::testport::text_blob("nce")[..]), 0, "`O` + `nce`: `Once`");
    crate::testport::assert_eq(it_join(en, 65, &crate::testport::text_blob("xyzzy")[..]), 1, "a word neither list knows: joined, flagged");
    crate::testport::assert_eq(it_join(en, 84, &crate::testport::text_blob("he")[..]), 0, "`T` is no word");
    crate::testport::assert_eq(it_join(en, 97, &crate::testport::text_blob("long")[..]), 2, "a lower-case letter is read as its capital");
    // A language with a one-letter table and no list joins and flags; one without the letter joins.
    crate::testport::assert_eq(it_join(de, 79, &crate::testport::text_blob("ma")[..]), 1, "German `O`");
    crate::testport::assert_eq(it_join(de, 65, &crate::testport::text_blob("long")[..]), 0, "German has no one-letter `A`");
    crate::testport::assert_eq(it_join(fr, 192, &crate::testport::text_blob("propos")[..]), 1, "French `À`");
    crate::testport::assert_eq(it_join(zh, 65, &crate::testport::text_blob("long")[..]), 1, "a language without a table: the union");
}
